// interceptor ôm CẢ 2 CHIỀU handler
intercept(ctx, next) {
  const t0 = Date.now(); // trước
  // next.handle() = Observable LAZY
  return next.handle().pipe(
    map((data) => {
      const tookMs = Date.now() - t0;
      ctx.switchToHttp().getResponse()
        .setHeader('X-Response-Time',
          `${tookMs}ms`);
      return { ok: true, data, tookMs };
    }),
  );
}
